import json,hashlib,subprocess,time
from pathlib import Path
from datetime import datetime,timezone,timedelta
ROOT=Path(__file__).resolve().parents[1];OUT=Path(__file__).resolve().parent
now=datetime.now(timezone(timedelta(hours=3)));head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT).decode().strip()
def read(p):return json.loads(Path(p).read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def atomic(path,data,before):
    temp=path.with_suffix(path.suffix+'.domain_result.pending');assert not temp.exists();temp.write_bytes(data)
    for _ in range(30):
        assert path.read_bytes()==before
        try:temp.replace(path);return
        except PermissionError:time.sleep(.1)
    raise PermissionError(str(path))
def update(path,obj,before):atomic(path,(json.dumps(obj,ensure_ascii=False,indent=2)+'\n').encode(),before)
