s['cases'].append(dict(date='2026-11-09',component='Обучение головы в рабочем допуске',fact=facts,hypothesis='Изменение распределения обучения проверено отдельно от координат; причинный вывод о полном трекере ещё отсутствует.',discriminating_check=decision,limitation='Малая разработческая выборка, нет новых полных траекторий или независимого финального теста.',evidence=[dict(source='research_domain_matched_reader_20261109/summary.json',sha256=sha(OUT/'summary.json'),claim='Результат неизменённой процедуры на новом рабочем пуле')]))
